query.base:
FROM metrics-gcp.cloudstorage.otel-default
// Scope to Cloud Storage; this data stream carries every GCP service the receiver collects.
| WHERE resource.attributes.gcp.resource_type == "gcs_bucket"
    AND `metrics.storage.googleapis.com/api/request_count` IS NOT NULL
// Client-fault codes other than the authorization pair, which has its own, traffic-normalised rule
// (gcp_cloudstorage_otel-authorization-failure-surge). Anything not listed here is handled by
// gcp_cloudstorage_otel-service-fault-errors, so the two rules together cover every possible code.
| WHERE attributes.response_code IN (
      "NOT_FOUND", "INVALID_ARGUMENT", "FAILED_PRECONDITION",
      "OUT_OF_RANGE", "ALREADY_EXISTS", "CANCELLED")
// Split the rule's 24h window into a 2h "recent" slice and a 22h baseline. A long baseline is used
// deliberately so that a normal diurnal peak is not mistaken for a step change.
| EVAL is_recent = @timestamp >= NOW() - 2 hours
// request_count is a ~60s delta counter stored as a gauge: SUM it, never RATE() it.
| STATS recent_faults    = SUM(`metrics.storage.googleapis.com/api/request_count`) WHERE is_recent,
        baseline_faults  = SUM(`metrics.storage.googleapis.com/api/request_count`) WHERE NOT is_recent,
        affected_methods = VALUES(attributes.method) WHERE is_recent
    BY resource.attributes.bucket_name, attributes.response_code
| EVAL recent_faults = COALESCE(recent_faults, 0), baseline_faults = COALESCE(baseline_faults, 0)

breach.segment:
// Absolute floor first, so a code that was previously absent cannot page on a handful of requests.
WHERE recent_faults >= 50
// Cast before dividing: request_count is a long and `a / b` would be integer division.
// 2.0 and 22.0 are the two slice widths in hours — keep them in sync with is_recent/timeWindowSize.
| EVAL recent_faults_per_hour   = ROUND(recent_faults::DOUBLE / 2.0, 2),
       baseline_faults_per_hour = ROUND(baseline_faults::DOUBLE / 22.0, 2)
// Step-change test on the unrounded hourly rates. A code with no baseline at all is compared
// against 1 fault/hour instead, so the ratio stays finite; the volume floor above already makes
// such a code significant.
| EVAL step_change_factor = ROUND((recent_faults::DOUBLE / 2.0)
      / CASE(baseline_faults > 0, baseline_faults::DOUBLE / 22.0, 1.0), 2)
| WHERE step_change_factor >= 3.0
| EVAL alert_key = CONCAT(resource.attributes.bucket_name, " / ", attributes.response_code)
| SORT step_change_factor DESC
| LIMIT 50
